// DEVDESK-201 D3: the prompt hands the whole message to its input, so a paste
// lands in the query (newlines become spaces) and neither confirms nor cancels.
func TestPasteReachesTheQuery(t *testing.T) {
	tests := []struct{ name, typed, paste, want string }{
		{"word", "", "devdesk", "devdesk"},
		{"appended", "dev", "desk", "devdesk"},
		{"multi-line", "", "a\nb", "a b"},
		{"action letters", "", "Dq?", "Dq?"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			f := New("Loading")
			for _, k := range testutil.Type(tc.typed) {
				f, _ = f.Update(k)
			}
			f, cmd := f.Update(testutil.Paste(tc.paste))
			if got := f.query.Value(); got != tc.want {
				t.Errorf("query = %q after pasting %q, want %q", got, tc.paste, tc.want)
			}
			for _, msg := range testutil.Msgs(cmd) {
				switch msg.(type) {
				case ConfirmMsg, CancelMsg:
					t.Errorf("the paste produced %T", msg)
				}
			}
		})
	}
}

// walkWorkspaceDirsCmd walks the whole workspaces root once, when the prompt
// opens — not on every keystroke.
func (m Model) walkWorkspaceDirsCmd() tea.Cmd {
	root := m.getExpandedWorkspacesDir()
	showHidden := m.config.App.ShowHiddenFiles

	return func() tea.Msg {
		result := collectDirs(root, showHidden)
		candidates := make([]fuzzy.Candidate, 0, len(result.Dirs))
		for _, dir := range result.Dirs {
			rel, err := filepath.Rel(root, dir)
			if err != nil || rel == "." {
				// The root itself: nothing to jump to that Home does not
				// already give.
				continue
			}
			candidates = append(candidates, dirCandidate(dir, filepath.ToSlash(rel)))
		}
		return FuzzyPathsLoadedMsg{Candidates: candidates, Skipped: result.Skipped}
	}
}

// dirCandidate is one directory the prompt can match: the absolute path is
// what jumping there needs, the forward-slash path relative to the workspaces
// root is what the query is matched against and what the results show.
func dirCandidate(abs, rel string) fuzzy.Candidate {
	return fuzzy.Candidate{Key: abs, Label: rel, Icon: theme.IconDirectory, Role: theme.IconRoleDirectory}
}

// collectDirs walks basePath and returns every directory under it, at any
const reasonNoIndexEntry = "That entry is no longer listed — ctrl+r to refresh"

// startFuzzyFind opens the prompt. Without an index yet the prompt still
// opens, saying it is waiting, and the router's next ForgeIndexChangedMsg
// fills it.
func (m Model) startFuzzyFind() (tea.Model, tea.Cmd) {
	if a := m.connected(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	m.mode = ModeFuzzyFinding
	m.finder = fuzzy.New("Indexing " + m.vocab().Name + "...")
	// Best-effort sizing; the router notices the footer height changed and
	// re-lays-out right after this returns (Rule 124).
	m.finder.Resize(m.width, m.height)
	if m.shared.ForgeIndex != nil {
		m.finder.SetCandidates(m.fuzzyCandidates(), m.shared.ForgeIndex.Skipped())
	}
	return m, nil
}

// fuzzyCandidates is every entry of the index, keyed and labelled by path.
func (m Model) fuzzyCandidates() []fuzzy.Candidate {
	entries := m.shared.ForgeIndex.All()
	out := make([]fuzzy.Candidate, len(entries))
	for i, e := range entries {
		icon, role := theme.IconRepository, theme.IconRoleRepository
		if e.Kind == forgeindex.KindNamespace {
			icon, role = theme.IconNamespace, theme.IconRoleNamespace
		}
		out[i] = fuzzy.Candidate{Key: e.Path, Label: e.Path, Icon: icon, Role: role}
	}
	return out
}

